import { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import {
  AlertTriangle, ArrowRight, Bell, CalendarDays, Check, CheckCircle2, ChevronRight,
  CircleDollarSign, CircleDot, ClipboardCheck, Clock3, Factory, Languages, Leaf,
  LogIn, LogOut, MapPin, Menu, MessageCircle, Mic, Navigation, Phone, Plus,
  RefreshCw, Route, Satellite, ShieldCheck, Store, Truck, Upload, UserRound,
  Wallet, Wifi, WifiOff, X
} from 'lucide-react';
import { supabase, supabaseConfigured } from './lib/supabase';
import { fields as demoFields, machines, buyers, steps, money } from './lib/data';
import './styles.css';

const STATUS = ['REGISTERED','BOOKED','MACHINE_ASSIGNED','ON_THE_WAY','BALING_IN_PROGRESS','CLEARED_PENDING_AUDIT','VERIFIED_NON_BURN','PAYMENT_PROCESSING','PAID'];
const statusIndex = s => Math.max(0, STATUS.indexOf(s));
const pretty = s => String(s || '').replaceAll('_', ' ');
const today = () => new Date().toISOString().slice(0, 10);
const addDays = (iso, days) => { const d = new Date(`${iso || today()}T00:00:00`); d.setDate(d.getDate() + days); return d.toISOString().slice(0, 10); };
const haversineKm = (a,b) => { if(!a||!b) return Infinity; const R=6371, p1=Number(a.lat)*Math.PI/180, p2=Number(b.lat)*Math.PI/180, dp=(Number(b.lat)-Number(a.lat))*Math.PI/180, dl=(Number(b.lng)-Number(a.lng))*Math.PI/180; const h=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2; return 2*R*Math.asin(Math.sqrt(h)); };
const sha256File = async file => { if(!globalThis.crypto?.subtle) return null; const buf=await file.arrayBuffer(); const hash=await crypto.subtle.digest('SHA-256',buf); return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join(''); };

function normalizeGeometry(g) {
  if (!Array.isArray(g) || g.length < 3) return null;
  if (g.every(p => Number.isFinite(Number(p.lat)) && Number.isFinite(Number(p.lng)))) return g.map(p => ({ lat: Number(p.lat), lng: Number(p.lng) }));
  if (g.every(p => Number.isFinite(Number(p.x)) && Number.isFinite(Number(p.y)))) return null;
  return null;
}
function normalizeField(f) {
  return {
    id: f.external_id || f.id,
    dbId: f.dbId || f.id,
    farmer: f.farmer || '', phone: f.phone || '', khasra: f.khasra_no || f.khasra || '',
    acres: Number(f.acreage ?? f.acres ?? 0), crop: f.crop || 'Paddy', variety: f.variety || '',
    harvest: f.expected_harvest_date || f.harvest || '', deadline: f.clearance_deadline || f.deadline || '',
    status: f.status || 'REGISTERED', village: f.village || '', block: f.block || '', district: f.district || '',
    moisture: Number(f.moisture_pct ?? f.moisture ?? 0), payout: Number(f.payout ?? 0),
    machine: f.machine || f.machine_id || '', lat: Number(f.center_lat ?? f.lat ?? 30.2285),
    lng: Number(f.center_lng ?? f.lng ?? 75.8214), verified: Boolean(f.verified ?? f.status === 'VERIFIED_NON_BURN'),
    geometry: normalizeGeometry(f.geometry || (Array.isArray(f.boundary_geojson?.coordinates?.[0]) ? f.boundary_geojson.coordinates[0].slice(0,-1).map(([lng,lat]) => ({lat,lng})) : null)),
    boundarySource: f.boundary_source || 'demo', boundaryVerified: Boolean(f.boundary_verified)
  };
}

function App() {
  const [tab, setTab] = useState('home');
  const [allFields, setAllFields] = useState(demoFields.map(normalizeField));
  const [selected, setSelected] = useState(normalizeField(demoFields[0]));
  const [booking, setBooking] = useState(null);
  const [session, setSession] = useState(null);
  const [profileRole, setProfileRole] = useState('farmer');
  const [notifications, setNotifications] = useState([]);
  const [online, setOnline] = useState(typeof navigator === 'undefined' ? true : navigator.onLine);
  const [authOpen, setAuthOpen] = useState(false);
  const [sathiOpen, setSathiOpen] = useState(false);
  const [networkOpen, setNetworkOpen] = useState(false);
  const [mobile, setMobile] = useState(false);
  const [toast, setToast] = useState('');
  const [loading, setLoading] = useState(false);
  const [lang, setLang] = useState('EN');
  const [weather, setWeather] = useState(null);
  const [paymentNotice, setPaymentNotice] = useState(null);
  const [quote, setQuote] = useState(null);
  const demoMode = !supabaseConfigured;

  const notify = message => {
    setToast(message);
    window.clearTimeout(window.__nirdhoomToast);
    window.__nirdhoomToast = window.setTimeout(() => setToast(''), 3000);
  };

  useEffect(() => {
    const onlineOn = () => setOnline(true);
    const onlineOff = () => setOnline(false);
    window.addEventListener('online', onlineOn);
    window.addEventListener('offline', onlineOff);
    return () => { window.removeEventListener('online', onlineOn); window.removeEventListener('offline', onlineOff); };
  }, []);

  useEffect(() => {
    if (!supabase) return undefined;
    let active = true;
    supabase.auth.getSession().then(({ data }) => { if (active) setSession(data.session); });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, next) => setSession(next));
    return () => { active = false; subscription.unsubscribe(); };
  }, []);

  const loadFields = async () => {
    if (!supabase || !session?.user) return notify(demoMode ? 'Demo fields are already loaded' : 'Sign in to refresh account data');
    setLoading(true);
    const { data, error } = await supabase.from('fields').select('*').order('created_at', { ascending: false });
    setLoading(false);
    if (error) return notify(error.message);
    if (!data?.length) return notify('No saved fields yet. Add your first field.');
    const fs = data.map(normalizeField);
    setAllFields(fs); setSelected(fs[0]);
  };

  useEffect(() => {
    if (!session?.user || !supabase) return;
    (async () => {
      const { data: profile } = await supabase.from('profiles').select('role,preferred_language').eq('id', session.user.id).maybeSingle();
      if (profile?.role) setProfileRole(profile.role);
      if (profile?.preferred_language === 'pa') setLang('ਪੰਜਾਬੀ');
      await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: session.user.user_metadata?.full_name || session.user.phone || 'Farmer',
        phone: session.user.phone || null
      }, { onConflict: 'id', ignoreDuplicates: false });
      await loadFields();
      const { data: notices } = await supabase.from('notifications').select('*').order('created_at', { ascending: false }).limit(20);
      if (notices) setNotifications(notices);
    })();
  }, [session?.user?.id]);

  useEffect(() => {
    if (!selected?.lat || !selected?.lng) return undefined;
    const controller = new AbortController();
    fetch(`https://api.open-meteo.com/v1/forecast?latitude=${selected.lat}&longitude=${selected.lng}&current=temperature_2m,relative_humidity_2m,precipitation,wind_speed_10m&daily=precipitation_probability_max&forecast_days=1&timezone=auto`, { signal: controller.signal })
      .then(r => r.ok ? r.json() : Promise.reject(new Error('Weather unavailable')))
      .then(setWeather).catch(() => setWeather(null));
    return () => controller.abort();
  }, [selected?.lat, selected?.lng]);

  const addField = async payload => {
    const external = `FIELD-${Date.now()}`;
    const boundary = Array.isArray(payload.geometry) && payload.geometry.length >= 3 ? payload.geometry : null;
    const center = boundary ? boundary.reduce((a, p) => ({ lat: a.lat + p.lat, lng: a.lng + p.lng }), { lat: 0, lng: 0 }) : { lat: Number(payload.center_lat || 30.2285), lng: Number(payload.center_lng || 75.8214) };
    const n = boundary ? boundary.length : 1;
    const base = { ...payload, external_id: external, acreage: Number(payload.acreage), center_lat: center.lat / n, center_lng: center.lng / n, geometry: boundary };
    if (supabase && session?.user) {
      const { data, error } = await supabase.from('fields').insert({ ...base, owner_id: session.user.id, boundary_geojson: boundary ? { type: 'Polygon', coordinates: [[...boundary.map(p => [p.lng, p.lat]), [boundary[0].lng, boundary[0].lat]]] } : null, boundary_source: boundary ? 'self_drawn' : 'manual', boundary_verified: false }).select().single();
      if (error) return notify(error.message);
      const f = normalizeField(data); setAllFields(x => [f, ...x]); setSelected(f); notify('Field added to your account'); return;
    }
    const f = normalizeField({ ...base, id: external, external_id: external });
    setAllFields(x => [f, ...x]); setSelected(f); notify('Demo field added. Connect Supabase to persist it.');
  };

  const getQuote = async (field, date) => {
    const daysToHarvest = field.harvest ? Math.round((new Date(`${field.harvest}T00:00:00`) - new Date(`${today()}T00:00:00`)) / 86400000) : 14;
    try {
      const r = await fetch('/api/quote', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ field: { acres: field.acres, harvest: field.harvest, block: field.block, lat: field.lat, lng: field.lng }, requested_date: date, days_to_harvest: daysToHarvest }) });
      if (r.ok) return await r.json();
    } catch (_) { /* deterministic fallback below */ }
    const early = Math.max(0, Math.min(21, daysToHarvest));
    const urgency = early <= 3 ? 1.28 : early <= 7 ? 1.12 : 0.96;
    const capacity = date ? (new Date(date).getDay() === 0 ? 1.14 : 1) : 1;
    const rate = Math.round(1500 * urgency * capacity / 10) * 10;
    const guaranteed = date || addDays(today(), 2);
    return { rate_per_acre: rate, quoted_amount: Math.round(rate * field.acres), guaranteed_by_date: guaranteed, penalty_amount: Math.round(Math.max(2500, field.acres * 2500)), pricing_band: urgency > 1.15 ? 'urgent' : urgency > 1 ? 'standard' : 'early-booking', reason_codes: ['days_to_harvest','capacity_window'] };
  };

  const book = async (date, providedQuote) => {
    if (!date) return notify('Choose a clearance date first');
    if (supabase && session?.user && !session.user.id) return notify('Sign in before booking');
    const q = providedQuote || await getQuote(selected, date);
    const local = { field: selected, date, total: q.quoted_amount, rate: q.rate_per_acre, guaranteedBy: q.guaranteed_by_date, penalty: q.penalty_amount, machine: machines.find(m => m.id === selected.machine) || machines[0] };
    if (supabase && session?.user && selected.dbId) {
      const { data, error } = await supabase.rpc('reserve_clearance_booking', {
        p_field_id: selected.dbId, p_requested_date: date, p_rate_per_acre: q.rate_per_acre,
        p_quoted_amount: q.quoted_amount, p_guaranteed_by_date: q.guaranteed_by_date,
        p_penalty_amount: q.penalty_amount, p_pricing_band: q.pricing_band, p_quote_metadata: q
      });
      if (error) return notify(error.message);
      const bookingRow = Array.isArray(data) ? data[0] : data;
      const updated = { ...selected, status: 'BOOKED', payout: q.quoted_amount, deadline: q.guaranteed_by_date };
      setSelected(updated); setAllFields(fs => fs.map(f => f.id === selected.id ? updated : f)); setBooking({ ...local, dbId: bookingRow?.id });
      await supabase.from('notifications').insert({ profile_id: session.user.id, title: 'Guaranteed clearance reserved', body: `Your field is booked for ${q.guaranteed_by_date}. Penalty basis: ${money(q.penalty_amount)}.` });
      setNotifications(n => [{ id: `local-${Date.now()}`, title: 'Guaranteed clearance reserved', body: `Booked for ${q.guaranteed_by_date}.` }, ...n]);
    } else {
      const updated = { ...selected, status: 'BOOKED', payout: q.quoted_amount, deadline: q.guaranteed_by_date };
      setSelected(updated); setAllFields(fs => fs.map(f => f.id === selected.id ? updated : f)); setBooking(local);
      setNotifications(n => [{ id: `local-${Date.now()}`, title: 'Clearance request created', body: `Demo booking: guaranteed target ${q.guaranteed_by_date}.` }, ...n]);
    }
    setPaymentNotice({ status: 'PENDING', amount: q.quoted_amount });
    setQuote(q); setTab('track'); notify('Clearance slot reserved with a locked quote');
  };

  const signOut = async () => { if (supabase) await supabase.auth.signOut(); setSession(null); setProfileRole('farmer'); setNotifications([]); notify('Signed out'); };
  const markNotificationRead = async id => { const readAt = new Date().toISOString(); setNotifications(ns => ns.map(n => n.id === id ? { ...n, read_at: readAt } : n)); if (supabase && session?.user && !String(id).startsWith('local-')) await supabase.from('notifications').update({ read_at: readAt }).eq('id', id); };
  const networkNavigate = target => {
    const allowed = !session || profileRole === 'admin' || (target === 'operator' && profileRole === 'operator') || (target === 'dispatch' && ['dispatcher','admin'].includes(profileRole)) || (target === 'verify' && ['verifier','dispatcher','admin'].includes(profileRole)) || (target === 'carbon' && ['verifier','dispatcher','admin'].includes(profileRole));
    if (!allowed) return notify('This operational surface is restricted to its assigned role.');
    setTab(target);
  };
  const displayFields = allFields.length ? allFields : [selected];
  const unread = notifications.filter(n => !n.read_at).length;
  const nav = [['home','Home'],['fields','My fields'],['book','Book clearance'],['track','Track'],['market','Residue'],['payment','Payments'],['impact','Impact']];

  return <div className="app">
    <header className="top">
      <div className="brand" onClick={() => setTab('home')}><div className="mark">N</div><div><b>NIRDHOOM</b><span>ਨਿਰਧੂਮ · Parali Reframe</span></div></div>
      <nav className={mobile ? 'open' : ''}>{nav.map(([id,label]) => <button key={id} className={tab === id ? 'active' : ''} onClick={() => { setTab(id); setMobile(false); }}>{label}</button>)}</nav>
      <div className="top-actions"><button className="lang" onClick={() => setLang(lang === 'EN' ? 'ਪੰਜਾਬੀ' : 'EN')}><Languages size={16}/>{lang}</button><button className="sathi" onClick={() => setSathiOpen(true)}><MessageCircle size={16}/>Sathi</button><button className="notif-btn" onClick={() => setNetworkOpen(true)} title="Open network"><Bell size={16}/>{unread > 0 && <span>{unread}</span>}</button>{session ? <button className="account" onClick={signOut}><LogOut size={16}/>Sign out</button> : <button className="account" onClick={() => setAuthOpen(true)}><LogIn size={16}/>Phone OTP</button>}<button className="hamb" onClick={() => setMobile(!mobile)}>{mobile ? <X/> : <Menu/>}</button></div>
    </header>
    <div className="subbar"><span><span className="dot"/> {demoMode ? 'Demo data' : 'Connected to Supabase'}{loading ? ' · syncing' : ''}</span><span className="network-status">{online ? <Wifi size={13}/> : <WifiOff size={13}/>} {online ? 'Online' : 'Offline'}</span><button onClick={loadFields}><RefreshCw size={14}/>Refresh</button><button onClick={() => setNetworkOpen(true)}><Factory size={14}/>Network</button></div>
    <main>
      {tab === 'home' && <Home selected={selected} session={session} weather={weather} onBook={() => setTab('book')} onFields={() => setTab('fields')} onSathi={() => setSathiOpen(true)} onSignIn={() => setAuthOpen(true)} />}
      {tab === 'fields' && <Fields selected={selected} setSelected={setSelected} fields={displayFields} onBook={() => setTab('book')} onAdd={addField} />}
      {tab === 'book' && <Book key={selected.id} selected={selected} book={book} initialQuote={quote} getQuote={getQuote} />}
      {tab === 'track' && <Track selected={selected} booking={booking} onNavigate={setTab} session={session} profileRole={profileRole} online={online} />}
      {tab === 'market' && <Market selected={selected} onNotify={notify} session={session} />}
      {tab === 'impact' && <Impact />}
      {tab === 'payment' && <Payments selected={selected} booking={booking} notice={paymentNotice} session={session} />}
      {tab === 'operator' && <Operator onNotify={notify} session={session} profileRole={profileRole} online={online} field={selected} />}
      {tab === 'dispatch' && <Dispatch onNotify={notify} session={session} />}
      {tab === 'verify' && <Verification onNotify={notify} selected={selected} session={session} />}
      {tab === 'carbon' && <Carbon />}
      {tab === 'intelligence' && <Intelligence selected={selected} weather={weather} onNotify={notify} />}
    </main>
    {toast && <div className="toast"><CheckCircle2 size={18}/>{toast}</div>}
    {authOpen && <Auth onClose={() => setAuthOpen(false)} onNotify={notify}/>} 
    {sathiOpen && <Sathi onClose={() => setSathiOpen(false)} field={selected} session={session} onNotify={notify} language={lang}/>} 
    {networkOpen && <Network onClose={() => setNetworkOpen(false)} onNavigate={networkNavigate}/>} 
    {notifications.length > 0 && <NotificationDock notifications={notifications.slice(0,5)} onRead={markNotificationRead}/>} 
    <footer><span><b>NIRDHOOM</b> · The Parali Reframe</span><span>Farmer-first crop residue network</span><span>Punjab</span></footer>
  </div>;
}

function Home({ selected, session, weather, onBook, onFields, onSathi, onSignIn }) {
  return <section className="container home"><div className="hero"><div><div className="eyebrow"><span className="dot"/>FIELD-FIRST CLEARANCE</div><h1>Clear your field.<br/><em>Keep your next crop on time.</em></h1><p>NIRDHOOM dispatches already-subsidised machinery, sells a clearance window, records field proof and connects residue to buyers.</p><div className="hero-actions"><button className="primary" onClick={onBook}>Book field clearance <ArrowRight size={18}/></button><button className="secondary" onClick={onFields}>View my fields</button></div><div className="trust"><span><ShieldCheck size={16}/>Field record</span><span><Wallet size={16}/>Per-acre payout</span><span><Leaf size={16}/>Multi-offtake</span></div>{!session&&<div className="login-hint"><UserRound size={16}/><span><b>Farmer login is phone-first.</b> Your consent and field records stay attached to your account.</span><button onClick={onSignIn}>Phone OTP</button></div>}</div><FieldMap field={selected}/></div><div className="section-head"><div><span className="eyebrow">THE LOOP</span><h2>Field → machine → evidence → residue → payment</h2></div><button className="text-btn" onClick={onSathi}><MessageCircle size={17}/>Ask NIRDHOOM Sathi</button></div><div className="cards four"><Action icon={<MapPin/>} n="01" title="Register field" text="Khasra, crop variety, acreage and real boundary."/><Action icon={<CalendarDays/>} n="02" title="Lock a slot" text="Dynamic per-acre quote with a target clearance date."/><Action icon={<Truck/>} n="03" title="Track machine" text="Operator job state and GPS when available."/><Action icon={<Wallet/>} n="04" title="Close the loop" text="Evidence, residue lot and provider-settled payment."/></div><PhotoBand/><div className="split"><div className="panel warm"><span className="eyebrow">CURRENT FIELD</span><h3>{selected.village}, {selected.district}</h3><div className="mini-grid"><Stat label="Acreage" value={`${selected.acres} ac`}/><Stat label="Variety" value={selected.variety || 'Paddy'}/><Stat label="Harvest" value={selected.harvest || 'Not set'}/><Stat label="Target payout" value={selected.payout ? money(selected.payout) : 'To quote'}/></div><button className="secondary" onClick={onFields}>Open field record <ChevronRight size={16}/></button></div><div className="panel green"><span className="eyebrow">LOCAL WEATHER</span>{weather?.current?<div className="weather-row"><div><b>{Math.round(weather.current.temperature_2m)}°C</b><span>Temperature</span></div><div><b>{Math.round(weather.current.relative_humidity_2m)}%</b><span>Humidity</span></div><div><b>{Math.round(weather.current.wind_speed_10m)} km/h</b><span>Wind</span></div><div><b>{weather.daily?.precipitation_probability_max?.[0] ?? '—'}%</b><span>Rain chance</span></div></div>:<p>Weather will load from the selected field location when available.</p>}<small className="source-note">Weather is advisory; final dispatch decisions use operational conditions.</small></div></div></section>;
}

function PhotoBand(){return <div className="photo-band"><div><img src="/images/punjab_farmer_hero.jpg" alt="Punjab farmer in a field"/><span>Farmer-first</span></div><div><img src="/images/baling_fleet.jpg" alt="Crop residue baling machinery"/><span>Idle machinery, routed</span></div><div><img src="/images/offtake_facility.jpg" alt="Residue offtake facility"/><span>Multiple offtake paths</span></div></div>}

function latLngToTile(lat,lng,z){const n=2**z,x=((lng+180)/360)*n,latRad=lat*Math.PI/180,y=(1-Math.asinh(Math.tan(latRad))/Math.PI)/2*n;return{x,y};}
function tileToLatLng(x,y,z){const n=2**z,lng=x/n*360-180,lat=180/Math.PI*Math.atan(Math.sinh(Math.PI*(1-2*y/n)));return{lat,lng};}
function FieldMap({field,editable=false,points=[],onMapClick}){
  const lat=Number(field?.lat)||30.2285,lng=Number(field?.lng)||75.8214,z=13,center=latLngToTile(lat,lng,z),baseX=Math.floor(center.x),baseY=Math.floor(center.y),tileSize=256;
  const tiles=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)tiles.push({x:baseX+dx,y:baseY+dy,dx,dy});
  const project=(la,lo)=>{const p=latLngToTile(la,lo,z);return{x:(p.x-(baseX-1))*tileSize,y:(p.y-(baseY-1))*tileSize};};
  const poly=Array.isArray(field?.geometry)&&field.geometry.length>=3?field.geometry.map(p=>project(p.lat,p.lng)):null;
  const drawn=points.length?points.map(p=>project(p.lat,p.lng)):null;
  const fallback=[{x:18,y:30},{x:84,y:24},{x:78,y:76},{x:31,y:84},{x:9,y:57}];
  return <div className={'map '+(editable?'map-edit':'')} onClick={e=>{if(!onMapClick)return;const r=e.currentTarget.getBoundingClientRect();const px=(e.clientX-r.left)/r.width*768,py=(e.clientY-r.top)/r.height*768;const tileX=baseX-1+px/256,tileY=baseY-1+py/256;onMapClick(tileToLatLng(tileX,tileY,z));}}><div className="tile-map">{tiles.map(t=><img key={`${t.dx}-${t.dy}`} src={`https://tile.openstreetmap.org/${z}/${t.x}/${t.y}.png`} alt="" loading="lazy"/> )}</div><svg viewBox="0 0 768 768" preserveAspectRatio="none"><polygon points={(poly||drawn||fallback).map(p=>`${p.x ?? (p.lat*0)},${p.y ?? 0}`).join(' ')} />{points.length>1&&<polyline points={drawn.map(p=>`${p.x},${p.y}`).join(' ')} />}</svg><div className="map-label"><MapPin size={15}/>{field?.acres?`${field.acres} acres`:'Field boundary'}</div><div className="map-scale">OpenStreetMap · field boundary</div>{editable&&<div className="map-help">Tap the map to add boundary points</div>}<div className="map-attribution">© OpenStreetMap contributors</div></div>;
}
function Action({icon,n,title,text}){return <div className="action-card"><div className="action-top"><span>{n}</span><div>{icon}</div></div><h3>{title}</h3><p>{text}</p></div>}
function Stat({label,value}){return <div><small>{label}</small><b>{value}</b></div>}

function Fields({selected,setSelected,fields,onBook,onAdd}){const[add,setAdd]=useState(false);return <section className="container page"><div className="page-title"><div><span className="eyebrow">MY FIELDS</span><h1>Field records</h1><p>Each field keeps identity, crop, harvest window, boundary provenance and evidence together.</p></div><button className="primary" onClick={()=>setAdd(true)}><Plus size={18}/>Add field</button></div><div className="field-layout"><div className="field-list">{fields.map(f=><button className={'field-row '+(selected.id===f.id?'selected':'')} key={f.id} onClick={()=>setSelected(f)}><div className="status-dot" data-status={f.status}/><div><b>{f.village||'Unnamed field'}</b><span>{f.khasra} · {f.acres} acres</span></div><div className="row-right"><small>{pretty(f.status)}</small><ChevronRight size={17}/></div></button>)}</div><FieldDetail f={selected} onBook={onBook}/></div>{add&&<AddField onClose={()=>setAdd(false)} onSave={p=>{setAdd(false);onAdd(p)}}/>}</section>}
function FieldDetail({f,onBook}){return <div className="panel detail"><div className="detail-head"><div><span className="eyebrow">FIELD RECORD</span><h2>{f.village||'Unnamed field'}, {f.district}</h2><p>{f.khasra} · {f.farmer||'Farmer record'}</p></div><span className="pill">{pretty(f.status)}</span></div><FieldMap field={f}/><div className="detail-grid"><Stat label="Crop / variety" value={`${f.crop} · ${f.variety||'Not set'}`}/><Stat label="Harvest window" value={f.harvest||'Not set'}/><Stat label="Clearance deadline" value={f.deadline||'Not set'}/><Stat label="Boundary" value={f.boundaryVerified?'Verified cadastral':'Demo / self-drawn'}/><Stat label="Assigned machine" value={f.machine||'Not assigned'}/><Stat label="Expected payout" value={f.payout?money(f.payout):'To quote'}/></div><div className="detail-actions"><button className="primary" onClick={onBook}>Book / update clearance <ArrowRight size={17}/></button><span className="evidence-chip"><Satellite size={15}/>{f.verified?'Evidence recorded':'Evidence pending'}</span></div></div>}
function AddField({onClose,onSave}){const[f,setF]=useState({khasra:'',village:'',block:'',district:'Sangrur',acreage:'',variety:'PR-126',expected_harvest_date:''});const[points,setPoints]=useState([]);const set=(k,v)=>setF(x=>({...x,[k]:v}));const save=()=>onSave({...f,geometry:points.length>=3?points:null});return <div className="overlay"><div className="modal modal-wide"><div className="modal-head"><div><span className="eyebrow">NEW FIELD</span><h2>Register field</h2></div><button onClick={onClose}><X/></button></div><div className="form-grid"><label>Khasra number<input value={f.khasra} onChange={e=>set('khasra',e.target.value)} placeholder="e.g. 412/1-2"/></label><label>Village<input value={f.village} onChange={e=>set('village',e.target.value)} placeholder="Village"/></label><label>Block<input value={f.block} onChange={e=>set('block',e.target.value)} placeholder="Block"/></label><label>District<input value={f.district} onChange={e=>set('district',e.target.value)}/></label><label>Acreage<input type="number" min="0.1" step="0.1" value={f.acreage} onChange={e=>set('acreage',e.target.value)} placeholder="3.5"/></label><label>Paddy variety<input value={f.variety} onChange={e=>set('variety',e.target.value)}/></label><label>Expected harvest<input type="date" value={f.expected_harvest_date} onChange={e=>set('expected_harvest_date',e.target.value)}/></label></div><div className="draw-box"><div><b>Field boundary</b><span>Draw a provisional polygon. Production cadastral/Khasra geometry must be verified before treating this as authoritative.</span></div><FieldMap field={{acres:null,lat:30.2285,lng:75.8214,geometry:null}} editable points={points} onMapClick={p=>setPoints(x=>[...x,p])}/><div className="draw-meta">{points.length} points · {points.length>=3?'Polygon ready':'Need at least 3 points'}</div><button className="secondary" onClick={()=>setPoints([])}>Clear boundary</button></div><div className="modal-actions"><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={!f.khasra||!f.village||Number(f.acreage)<=0} onClick={save}>Save field</button></div></div></div>}

function Book({selected,book,initialQuote,getQuote}){const[date,setDate]=useState(selected.harvest||addDays(today(),2));const[q,setQ]=useState(initialQuote);const[loading,setLoading]=useState(false);useEffect(()=>{let dead=false;setLoading(true);getQuote(selected,date).then(v=>{if(!dead)setQ(v)}).finally(()=>!dead&&setLoading(false));return()=>{dead=true}},[selected.id,date]);const total=q?.quoted_amount||Math.round(selected.acres*1500);return <section className="container page narrow"><div className="page-title"><div><span className="eyebrow">BOOK CLEARANCE</span><h1>Sell certainty, not price.</h1><p>Your quote changes with harvest urgency and network capacity. The production contract must define the actual service guarantee.</p></div></div><div className="booking-grid"><div className="panel"><div className="selected-field"><div className="field-icon"><Leaf/></div><div><b>{selected.village}</b><span>{selected.khasra} · {selected.acres} acres · {selected.variety}</span></div><span className="pill">Selected</span></div><label>Preferred clearance date<input type="date" min={today()} value={date} onChange={e=>setDate(e.target.value)}/></label>{q&&<div className="quote-grid"><Stat label="Rate / acre" value={money(q.rate_per_acre)}/><Stat label="Total" value={money(total)}/><Stat label="Target by" value={q.guaranteed_by_date}/><Stat label="Penalty basis" value={money(q.penalty_amount)}/></div>}<div className="quote"><span>{loading?'Repricing…':`Pricing band: ${q?.pricing_band||'calculating'}`}</span><b>{money(total)}</b></div><div className="note"><ShieldCheck size={17}/><div><b>Guarantee object</b><span>{q?`Target date ${q.guaranteed_by_date}; penalty basis ${money(q.penalty_amount)}. This is a demo contract object until a production policy and underwriting ledger are connected.`:'Calculating quote…'}</span></div></div><button className="primary wide" disabled={loading||!q} onClick={()=>book(date,q)}>Confirm clearance request <ArrowRight size={18}/></button></div><div className="panel side-info"><span className="eyebrow">P0 TRANSACTION</span>{steps.map((s,i)=><div className="flow" key={s[0]}><span>{i+1}</span><div><b>{s[0]}</b><small>{s[1]}</small></div></div>)}<div className="note"><Clock3 size={17}/><div><b>Why per acre?</b><span>Field area is directly tied to the registered polygon; it avoids farmgate weighment disputes at booking.</span></div></div></div></div></section>}

function Track({selected,booking,onNavigate,session,profileRole,online}){const machine=machines.find(m=>m.id===selected.machine)||machines[0];const current=Math.min(steps.length-1,Math.max(-1,statusIndex(selected.status)-1));return <section className="container page"><div className="page-title"><div><span className="eyebrow">TRACK CLEARANCE</span><h1>{selected.village}</h1><p>{selected.khasra} · {selected.acres} acres · {selected.variety}</p></div><span className="live"><span className="dot"/>{booking?'Request active':'Field status'}</span></div><div className="track-grid"><div className="panel timeline"><div className="panel-title"><h3>Clearance journey</h3><span>{pretty(selected.status)}</span></div>{steps.map((s,i)=><div className={'timeline-step '+(i<=current?'done':'')} key={s[0]}><div className="line-dot">{i<=current?<CheckCircle2 size={17}/>:i===current+1?<Clock3 size={16}/>:<span>{i+1}</span>}</div><div><b>{s[0]}</b><p>{s[1]}</p>{i===current&&<small className="current">Current stage</small>}</div></div>)}</div><div className="right-stack"><div className="panel machine"><div className="panel-title"><h3>Assigned machine</h3><span className="pill">{machine.status}</span></div><div className="machine-art"><Truck size={44}/><div><b>{machine.name}</b><span>{machine.type}</span></div></div><div className="machine-info"><Stat label="Operator" value={machine.operator}/><Stat label="Capacity" value={`${machine.capacity} ac/day`}/><Stat label="Fuel" value={`${machine.fuel}%`}/></div><a className="secondary wide" href={`tel:${machine.phone}`}><Phone size={16}/>Contact operator</a></div><div className="panel"><span className="eyebrow">LIVE OPERATIONS</span><div className="ops-mini"><span><CircleDot/> {online?'GPS online':'GPS offline'}</span><span><Navigation/> Route-ready</span><span><ClipboardCheck/> Proof-ready</span></div>{profileRole==='operator'&&<button className="secondary wide" onClick={()=>onNavigate('operator')}>Open operator app <ArrowRight size={15}/></button>}{['dispatcher','admin'].includes(profileRole)&&<button className="secondary wide" onClick={()=>onNavigate('dispatch')}>Open dispatch view <ArrowRight size={15}/></button>}</div><div className="panel evidence"><span className="eyebrow">VERIFICATION</span><h3>{selected.verified?'Non-burn evidence recorded':'Evidence will be added after clearance'}</h3><p>Remote sensing is one input. The production certificate should combine geometry, machine event, photos and satellite observations with a human review.</p><button className="text-btn" onClick={()=>onNavigate('verify')}>View evidence layer <ArrowRight size={15}/></button></div></div></div></section>}

function Market({selected,onNotify,session}){const[offers,setOffers]=useState([]);const[lots,setLots]=useState([]);const[credits,setCredits]=useState(0);const[busy,setBusy]=useState('');const load=async()=>{if(!supabase||!session?.user)return;const[{data:o},{data:l},{data:w}]=await Promise.all([supabase.from('buyer_offers').select('*,buyers(name,pathway)').eq('status','OPEN').limit(20),supabase.from('residue_lots').select('*').eq('field_id',selected.dbId).order('created_at',{ascending:false}).limit(10),supabase.from('credit_wallets').select('balance').eq('profile_id',session.user.id).maybeSingle()]);setOffers(o||[]);setLots(l||[]);setCredits(Number(w?.balance||0))};useEffect(()=>{load()},[session?.user?.id,selected.dbId]);const accept=async id=>{if(!supabase||!session?.user)return onNotify('Buyer login is required for offer acceptance');setBusy(id);const{error}=await supabase.rpc('accept_buyer_offer',{p_offer_id:id});setBusy('');if(error)onNotify(error.message);else{onNotify('Offer accepted and lot allocation locked');load()}};return <section className="container page"><div className="page-title"><div><span className="eyebrow">RESIDUE MARKET</span><h1>Route each lot to the highest-value eligible path.</h1><p>CBG is one buyer, not the entire market. Moisture, quality, distance and contracts should drive matching.</p></div></div><div className="market-top"><div className="panel green"><span className="eyebrow">CURRENT LOTS</span><h3>{lots.length?`${lots.length} linked lot(s)`:'No cleared lots yet'}</h3><p>Every lot should carry quantity, moisture, QR identity and chain-of-custody before an offer can be settled.</p><div className="lot-list">{lots.map(l=><div className="dispatch-row" key={l.id}><div><b>{l.qr_code||'Pending QR'}</b><span>{Number(l.quantity_tonnes||0).toFixed(2)} t · {l.moisture_pct||'—'}% moisture</span></div><span className="tag">{l.status}</span></div>)}</div><div className="detail-grid"><Stat label="Wallet credits" value={money(credits)}/><Stat label="Field" value={selected.external_id||selected.id}/></div></div><div className="panel"><span className="eyebrow">AUCTION RULE</span><h3>Eligibility first</h3><p>Only offers within moisture, quantity, distance and contract constraints should reach a buyer. Acceptance is transactional and cannot double-allocate a lot.</p></div></div><div className="buyer-grid">{buyers.map(b=><div className="buyer" key={b.name}><div className="buyer-top"><span className="tag">{b.tag}</span><Store size={18}/></div><h3>{b.name}</h3><p>{b.use}</p><div className="buyer-bottom"><b>{money(b.price)}<small>/ tonne</small></b><span>Moisture ≤ {b.ceiling}%</span></div><button className="secondary wide" onClick={()=>onNotify(`Buyer ${b.name}: live contracts are matched against lot constraints`)}>View pathway</button></div>)}</div>{offers.length>0&&<div className="panel"><div className="panel-title"><h3>Open buyer offers</h3><span className="pill">{offers.length}</span></div>{offers.map(o=><div className="dispatch-row" key={o.id}><div><b>{o.buyers?.name||'Buyer'} · {money(o.price_per_tonne)}/t</b><span>{o.quantity_tonnes} tonnes · valid until {o.valid_until||'not set'}</span></div><button className="secondary" disabled={busy===o.id} onClick={()=>accept(o.id)}>{busy===o.id?'Locking…':'Accept offer'}</button></div>)}</div>}{!session&&<div className="panel note"><Wallet size={17}/><div><b>Farmer-facing market</b><span>Farmers can view their own lot state; buyer acceptance is restricted by RLS and role.</span></div></div>}</section>}

function Impact(){return <section className="container page"><div className="page-title"><div><span className="eyebrow">IMPACT</span><h1>Make every cleared acre count.</h1><p>Prototype indicators are based on supplied demo records, not independently verified network totals.</p></div></div><div className="metrics"><div className="metric"><Leaf/><b>88.4</b><span>demo acres scheduled</span></div><div className="metric"><Truck/><b>4</b><span>demo machines</span></div><div className="metric"><Wallet/><b>₹1.28L</b><span>demo payout ledger</span></div><div className="metric"><ShieldCheck/><b>5</b><span>demo field records</span></div></div><div className="panel impact-panel"><div><span className="eyebrow">NORTH STAR</span><h2>Reliable clearance is the product.</h2><p>Straw collection is the acquisition hook; the long-term network is the verified, geo-tagged and financially-connected farmer relationship.</p></div><div className="loop">{['Field','Dispatch','Baling','Evidence','Offtake'].map((x,i)=><div key={x}><span>{i+1}</span><b>{x}</b>{i<4&&<ArrowRight/>}</div>)}</div></div></section>}

function Operator({onNotify,session,profileRole,online,field}){const key=`nirdhoom.operator.${session?.user?.id||'demo'}.${field?.id||'field'}`;const[job,setJob]=useState(()=>localStorage.getItem(`${key}.job`)||'ASSIGNED');const[queue,setQueue]=useState(()=>{try{return JSON.parse(localStorage.getItem(`${key}.queue`)||'[]')}catch{return[]}});const[gps,setGps]=useState(null);const[gpsError,setGpsError]=useState('');const[watching,setWatching]=useState(false);const[bookingRow,setBookingRow]=useState(null);const[busy,setBusy]=useState(false);const watchRef=useRef(null);const labels={ASSIGNED:'Assigned',ARRIVED:'Arrived at field',BALING:'Baling in progress',PROOF_PENDING:'Upload proof',COMPLETED:'Job completed'};const next={ASSIGNED:'ARRIVED',ARRIVED:'BALING',BALING:'PROOF_PENDING',PROOF_PENDING:'COMPLETED'};useEffect(()=>{if(!supabase||!session?.user||!field?.dbId)return;supabase.from('bookings').select('*').eq('field_id',field.dbId).not('status','eq','CANCELLED').order('created_at',{ascending:false}).limit(1).maybeSingle().then(({data})=>setBookingRow(data||null));return()=>{if(watchRef.current&&navigator.geolocation)navigator.geolocation.clearWatch(watchRef.current)}},[session?.user?.id,field?.dbId]);const startGps=()=>{if(!navigator.geolocation)return setGpsError('Geolocation is not supported');if(profileRole!=='operator')return setGpsError('Operator role required');setWatching(true);watchRef.current=navigator.geolocation.watchPosition(async p=>{const point={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,speed:p.coords.speed||0,recorded_at:new Date().toISOString()};setGps(point);if(supabase&&session?.user){const{data:m}=await supabase.from('machines').select('id').eq('operator_user_id',session.user.id).maybeSingle();if(m)await supabase.from('machine_locations').insert({machine_id:m.id,latitude:point.lat,longitude:point.lng,speed_kmh:point.speed*3.6,source:'browser_pwa',recorded_at:point.recorded_at})}},e=>setGpsError(e.message),{enableHighAccuracy:true,maximumAge:5000,timeout:15000})};const stopGps=()=>{if(watchRef.current&&navigator.geolocation)navigator.geolocation.clearWatch(watchRef.current);watchRef.current=null;setWatching(false)};const transition=async()=>{const n=next[job];if(!n)return;if(n==='ARRIVED'&&gps&&haversineKm(gps,field)>1)return onNotify(`You are ${haversineKm(gps,field).toFixed(1)} km from the field; arrival is blocked until GPS is near the field.`);setBusy(true);if(supabase&&session?.user&&bookingRow){const{data:jobs,error}=await supabase.from('jobs').select('id,status').eq('booking_id',bookingRow.id).maybeSingle();if(error){setBusy(false);return onNotify(error.message)}if(!jobs){setBusy(false);return onNotify('Dispatch has not assigned a job yet. Run dispatch before starting field work.')}const{error:e}=await supabase.rpc('transition_job',{p_job_id:jobs.id,p_next_status:n,p_metadata:{gps,online,client:'operator-pwa'}});if(e){setBusy(false);return onNotify(e.message)}}else if(!supabase){/* demo state only */}else{setBusy(false);return onNotify('No active booking found for this field')}setJob(n);localStorage.setItem(`${key}.job`,n);setBusy(false);onNotify(`Job moved to ${labels[n]}`)};const addProof=async e=>{const file=e.target.files?.[0];if(!file)return;const sha=await sha256File(file);const item={id:Date.now(),type:'field-proof',name:file.name,created_at:new Date().toISOString(),sync_status:online?'ready':'queued',sha256:sha};if(!online||!supabase||!session?.user||!field?.dbId||!bookingRow){const q=[item,...queue];setQueue(q);localStorage.setItem(`${key}.queue`,JSON.stringify(q));return onNotify('Proof queued locally for authenticated sync')};const path=`${session.user.id}/${field.dbId}/${item.id}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('evidence').upload(path,file,{contentType:file.type,upsert:false});if(up.error){const q=[item,...queue];setQueue(q);localStorage.setItem(`${key}.queue`,JSON.stringify(q));return onNotify(up.error.message)}const{error}=await supabase.from('evidence_assets').insert({field_id:field.dbId,booking_id:bookingRow.id,kind:'field_photo',storage_path:up.data.path,source:'operator_pwa',captured_at:item.created_at,latitude:gps?.lat,longitude:gps?.lng,gps_accuracy_m:gps?.accuracy,sha256:sha,sync_source:'online',created_by:session.user.id,metadata:{filename:file.name,size:file.size,mime:file.type}});if(error)onNotify(error.message);else{await supabase.from('field_events').insert({field_id:field.dbId,event_type:'PROOF_CAPTURED',actor_id:session.user.id,metadata:{sha256:sha,storage_path:up.data.path,latitude:gps?.lat,longitude:gps?.lng}});onNotify('Evidence uploaded with GPS, timestamp and SHA-256')} };const syncQueue=async()=>{if(!online||!supabase||!session?.user||!queue.length)return onNotify('Nothing to sync');onNotify('Queued evidence will sync when its booking is available; local metadata retained for safety.')};return <section className="container page narrow"><div className="page-title"><div><span className="eyebrow">OPERATOR PWA</span><h1>One job, one verified handoff.</h1><p>Offline-first field execution with real GPS, proximity checks, evidence hashes and controlled job transitions.</p></div><span className="live"><span className="dot"/>{online?'Online':'Offline'}</span></div>{profileRole!=='operator'&&<div className="note"><AlertTriangle size={17}/><div><b>Operator role required</b><span>Demo state is visible, but production GPS/job writes are RLS-protected.</span></div></div>}<div className="operator-card panel"><div className="job-head"><div><span className="pill">{bookingRow?.id?'LIVE JOB':'WAITING FOR DISPATCH'}</span><h2>{field.village||'Field'} · {field.id}</h2><p>{field.acres} acres · {field.variety} · deadline {field.deadline||'not set'}</p></div><Truck size={42}/></div><div className="job-route"><div><MapPin/><b>Machine</b><small>GPS tracked</small></div><Route/><div><MapPin/><b>{field.village||'Field'}</b><small>{field.boundaryVerified?'Verified geometry':'Provisional geometry'}</small></div></div><div className="operator-progress">{Object.keys(labels).map((x,i)=><div className={Object.keys(labels).indexOf(job)>=i?'done':''} key={x}><span>{i+1}</span><small>{labels[x]}</small></div>)}</div><div className="operator-actions"><button className="primary" disabled={busy||job==='COMPLETED'||!bookingRow} onClick={transition}>{job==='COMPLETED'?'Completed':labels[next[job]]||'Await dispatch'}</button><label className="secondary file-btn"><Upload/>Add proof<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={addProof}/></label></div><div className="gps-box"><div><b>Machine GPS</b><span>{gps?`${gps.lat.toFixed(5)}, ${gps.lng.toFixed(5)} · ±${Math.round(gps.accuracy)}m · ${haversineKm(gps,field).toFixed(2)} km from field`:gpsError||'Not started'}</span></div>{watching?<button className="secondary" onClick={stopGps}>Stop GPS</button>:<button className="secondary" onClick={startGps}>Start GPS</button>}</div><div className="sync-queue"><span><ClipboardCheck size={14}/> Offline evidence queue</span><b>{queue.length}</b><small>{queue.length?'Metadata is retained locally until sync.':'No pending local items.'}</small><button className="text-btn" onClick={syncQueue}>Sync check <RefreshCw size={14}/></button></div><ResidueLotForm field={field} session={session} booking={bookingRow} enabled={job==='COMPLETED'} onNotify={onNotify}/></div></section>}

function ResidueLotForm({field,session,booking,enabled,onNotify}){const[q,setQ]=useState('');const[m,setM]=useState('');const[w,setW]=useState('');const[busy,setBusy]=useState(false);const create=async()=>{if(!enabled||!field?.dbId||!booking?.id)return;if(Number(q)<=0)return onNotify('Enter the lot quantity in tonnes');setBusy(true);const row={field_id:field.dbId,booking_id:booking.id,quantity_tonnes:Number(q),weight_kg:Number(w||q*1000),moisture_pct:Number(m||0),qr_code:`NIR-${Date.now()}`,baled_at:new Date().toISOString(),moisture_checked_at:new Date().toISOString(),status:'AVAILABLE',chain_of_custody:{created_by:session?.user?.id||'demo'}};if(supabase&&session?.user){const{error}=await supabase.from('residue_lots').insert(row);if(error)onNotify(error.message);else onNotify(`Lot ${row.qr_code} recorded and ready for buyer matching`)}else onNotify(`Demo lot ${row.qr_code} prepared; connect Supabase to persist it`);setBusy(false)};return <div className="lot-form"><div><span className="eyebrow">RESIDUE LOT</span><b>{enabled?'Record the cleared lot':'Complete clearance before recording the lot'}</b></div><div className="form-grid"><label>Quantity (tonnes)<input type="number" min="0.1" step="0.1" value={q} onChange={e=>setQ(e.target.value)}/></label><label>Weight (kg)<input type="number" min="1" step="1" value={w} onChange={e=>setW(e.target.value)}/></label><label>Moisture %<input type="number" min="0" max="100" step="0.1" value={m} onChange={e=>setM(e.target.value)}/></label></div><button className="secondary" disabled={!enabled||busy} onClick={create}>{busy?'Recording…':'Create QR-tagged lot'}</button></div>}

function Dispatch({onNotify,session}){const[plan,setPlan]=useState(null);const[running,setRunning]=useState(false);const[rows,setRows]=useState([]);const load=async()=>{if(!supabase||!session?.user)return;const{data,error}=await supabase.from('bookings').select('id,field_id,requested_date,guaranteed_by_date,status,quoted_amount,machine_id,fields(id,external_id,village,block,acreage,center_lat,center_lng,expected_harvest_date,clearance_deadline,status)').in('status',['BOOKED','MACHINE_ASSIGNED']);if(error)return onNotify(error.message);setRows(data||[])};useEffect(()=>{load()},[session?.user?.id]);const run=async()=>{setRunning(true);try{const fields=rows.map(b=>({id:b.field?.external_id||b.field_id,db_id:b.field_id,lat:Number(b.field?.center_lat),lng:Number(b.field?.center_lng),acres:Number(b.field?.acreage),deadline:b.guaranteed_by_date||b.field?.clearance_deadline||b.requested_date,booking_id:b.id}));const liveMachines=supabase&&session?.user?(await supabase.from('machines').select('id,external_id,current_lat,current_lng,capacity_acres_day,status,operator_user_id')).data||[]:[];const ms=liveMachines.length?liveMachines.map(m=>({id:m.external_id||m.id,db_id:m.id,lat:Number(m.current_lat||30.2285),lng:Number(m.current_lng||75.8214),capacity_acres_day:Number(m.capacity_acres_day||0),status:m.status})):machines.map(m=>({id:m.id,lat:m.lat,lng:m.lng,capacity_acres_day:m.capacity,status:m.status}));const r=await fetch('/api/dispatch',{method:'POST',headers:{'Content-Type':'application/json',...(session?.access_token?{Authorization:`Bearer ${session.access_token}`}:{})},body:JSON.stringify({fields,machines:ms})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Dispatch unavailable');setPlan(data);if(supabase&&session?.user&&data.routes){for(const route of data.routes){for(const stop of route.stops||[]){const b=rows.find(x=>(x.field?.external_id||x.field_id)===stop);const m=liveMachines.find(x=String(x.external_id||x.id)===String(route.machine_id));if(b&&m){const startAt=new Date(`${b.guaranteed_by_date||b.requested_date}T08:00:00+05:30`);const endAt=new Date(startAt.getTime()+Math.max(60,Math.ceil(Number(b.field?.acreage||1)/Math.max(0.1,Number(m.capacity_acres_day||1))*8*60))*60000);await supabase.from('bookings').update({machine_id:m.id,assigned_at:new Date().toISOString(),accepted_at:new Date().toISOString(),status:'MACHINE_ASSIGNED'}).eq('id',b.id);await supabase.from('jobs').upsert({booking_id:b.id,machine_id:m.id,operator_id:m.operator_user_id,slot_start:startAt.toISOString(),slot_end:endAt.toISOString(),status:'ASSIGNED',route_metadata:{engine:data.engine,route:data.routes}} ,{onConflict:'booking_id'});}}}}await load();onNotify(data.engine==='ortools'?'OR-Tools plan assigned to live bookings':'Fallback plan returned; verify before production assignment')}catch(e){onNotify(e.message)}finally{setRunning(false)}};return <section className="container page"><div className="page-title"><div><span className="eyebrow">DISPATCH ENGINE</span><h1>Optimize the guarantee, not the map.</h1><p>Live bookings are assigned against capacity and deadlines. The OR-Tools service is the production solver; fallback is explicitly marked.</p></div><button className="primary" disabled={running||!rows.length} onClick={run}><Route/>{running?'Solving…':'Run route pass'}</button></div><div className="metrics"><div className="metric"><AlertTriangle/><b>{rows.length}</b><span>live bookings</span></div><div className="metric"><Truck/><b>{machines.filter(m=>m.status==='IDLE').length}</b><span>demo idle machines</span></div><div className="metric"><Clock3/><b>hard windows</b><span>guarantee constrained</span></div><div className="metric"><ShieldCheck/><b>{plan?.engine||'ready'}</b><span>solver state</span></div></div>{plan&&<div className="panel"><div className="panel-title"><h3>Returned plan</h3><span className="pill">{plan.engine}</span></div>{plan.routes?.map((r,i)=><div className="dispatch-row" key={r.machine_id||i}><div><b>{r.machine_id}</b><span>{(r.stops||[]).join(' → ')||'No stops'} · {r.total_acres||0} acres</span></div><span className="tag">{r.status||'PLANNED'}</span></div>)}</div>}<div className="panel"><div className="panel-title"><h3>Live booking queue</h3><span className="pill">{rows.length}</span></div>{rows.map(b=><div className="dispatch-row" key={b.id}><div><b>{b.field?.village||'Field'} · {Number(b.field?.acreage||0)} ac</b><span>{b.field?.variety||'Paddy'} · guarantee {b.guaranteed_by_date||b.requested_date}</span></div><span className="tag">{b.status}</span></div>)}</div></section>}

function Verification({onNotify,selected,session}){const[fire,setFire]=useState(null);const[evidence,setEvidence]=useState([]);const[lots,setLots]=useState([]);const[review,setReview]=useState('');const[loading,setLoading]=useState(false);const load=async()=>{if(!supabase||!session?.user||!selected?.dbId)return;const[{data:e},{data:l}]=await Promise.all([supabase.from('evidence_assets').select('*').eq('field_id',selected.dbId).order('created_at',{ascending:false}).limit(20),supabase.from('residue_lots').select('*').eq('field_id',selected.dbId).order('created_at',{ascending:false}).limit(10)]);setEvidence(e||[]);setLots(l||[])};useEffect(()=>{load()},[selected.dbId,session?.user?.id]);const refresh=async()=>{setLoading(true);try{const r=await fetch('/api/firms',{method:'POST',headers:{'Content-Type':'application/json',...(session?.access_token?{Authorization:`Bearer ${session.access_token}`}:{})},body:JSON.stringify({field:{dbId:selected.dbId,lat:selected.lat,lng:selected.lng,geometry:selected.geometry},radius_km:12})});const d=await r.json();if(!r.ok)throw new Error(d.error||'FIRMS unavailable');setFire(d);if(supabase&&session?.user&&selected.dbId){await supabase.from('firms_observations').insert((d.observations||[]).map(o=>({source:'NASA FIRMS',sensor:d.sensor,latitude:o.latitude,longitude:o.longitude,acquired_at:o.acq_datetime||null,confidence:o.confidence||null,frp:Number(o.frp||0),matched_field_id:d.matched_count&&d.matched_observations?.some(x=>x.latitude===o.latitude&&x.longitude===o.longitude)?selected.dbId:null,raw:o})));}onNotify(`FIRMS: ${d.count} nearby observations; ${d.matched_count||0} matched this field`)}catch(e){onNotify(e.message)}finally{setLoading(false)}};const decide=async result=>{if(!supabase||!session?.user)return onNotify('Verifier login is required');const{error}=await supabase.rpc('record_verification_review',{p_field_id:selected.dbId,p_result:result,p_confidence:result==='VERIFIED_NON_BURN'?90:20,p_metadata:{firms:fire,evidence_count:evidence.length,lot_count:lots.length,reviewed_at:new Date().toISOString()}});if(error)onNotify(error.message);else{setReview(result);onNotify(`Verification decision recorded: ${result}`)}};const ready=evidence.length>0&&lots.length>0&&Boolean(fire);return <section className="container page"><div className="page-title"><div><span className="eyebrow">VERIFICATION</span><h1>Evidence, not a magic badge.</h1><p>Verification is a joined record of geometry, operator evidence, residue custody and remote sensing. Human review remains the final decision.</p></div><button className="secondary" onClick={refresh} disabled={loading}><Satellite/>{loading?'Refreshing…':'Refresh FIRMS'}</button></div><div className="evidence-grid"><div className="panel"><div className="panel-title"><h3>Audit checklist</h3><Satellite/></div>{[['Field geometry',selected.boundaryVerified?'Verified cadastral':'Provisional / demo',selected.boundaryVerified],['Clearance evidence',`${evidence.length} asset(s)`,evidence.length>0],['Residue lot',`${lots.length} lot(s)`,lots.length>0],['Remote sensing',fire?`${fire.count} nearby / ${fire.matched_count||0} matched`:'Not pulled',Boolean(fire)],['Review',review||'Awaiting verifier',Boolean(review)]].map(([a,b,ok])=><div className="check-row" key={a}><CheckCircle2/><div><b>{a}</b><span>{b}</span></div><small>{ok?'READY':'PENDING'}</small></div>)}<div className="review-actions"><button className="primary" disabled={!ready} onClick={()=>decide('VERIFIED_NON_BURN')}>Record verified</button><button className="secondary" onClick={()=>decide('REVIEW_REQUIRED')}>Needs review</button></div></div><div className="panel satellite-panel"><span className="eyebrow">REMOTE SENSING LIMIT</span><h2>VIIRS is a signal, not field-level truth.</h2><p>FIRMS detections are evidence inputs. A missing detection does not prove that a field did not burn; timing, clouds, geometry and small fires can create gaps.</p>{fire&&<div className="fire-summary"><Stat label="Nearby observations" value={fire.count}/><Stat label="Field matches" value={fire.matched_count}/><Stat label="Sensor" value={fire.sensor}/></div>}<div className="evidence-list">{evidence.slice(0,6).map(e=><div className="dispatch-row" key={e.id}><div><b>{e.kind}</b><span>{e.captured_at||e.created_at} · {e.sha256?'SHA-256 recorded':'hash missing'}</span></div><span className="tag">{e.source}</span></div>)}</div><div className="note"><AlertTriangle size={17}/><div><b>Product rule</b><span>Store source, timestamp, geometry, confidence and human decision. Never turn zero FIRMS detections into absolute proof.</span></div></div></div></div></section>}

function Carbon(){return <section className="container page narrow"><div className="page-title"><div><span className="eyebrow">CARBON</span><h1>Build the chain before the claim.</h1><p>Carbon is downstream of verified operations, residue destination, methodology, additionality/eligibility rules and independent verification.</p></div></div><div className="carbon-chain">{[['01','Field','Polygon + crop + harvest'],['02','Clearance','Machine + timestamp + GPS'],['03','Residue','Quantity + moisture + destination'],['04','Evidence','Remote sensing + human review'],['05','Carbon record','Methodology + audit + registry']].map(([n,a,b])=><div className="carbon-step" key={n}><span>{n}</span><div><b>{a}</b><small>{b}</small></div></div>)}</div><div className="panel"><span className="eyebrow">P2 ROADMAP</span><h3>Carbon issuance ledger</h3><p>Implement methodology configuration, eligibility, chain-of-custody, verification and registry identifiers only after the operational evidence chain is complete.</p></div></section>}

function Intelligence({selected,weather,onNotify}){const[pH,setPH]=useState('');const[n,setN]=useState('');const[p,setP]=useState('');const[k,setK]=useState('');const[plan,setPlan]=useState(null);const makePlan=()=>{const notes=[];const ph=Number(pH),nn=Number(n),pp=Number(p),kk=Number(k);if(Number.isFinite(ph)){if(ph<6)notes.push('Prioritise an agronomist-reviewed liming plan before the next crop.');else if(ph>8)notes.push('Prioritise an agronomist-reviewed pH correction plan; avoid guessing doses.');else notes.push('pH is in a broadly workable range; maintain organic matter and test trends.')}if(Number.isFinite(nn))notes.push(nn<280?'Nitrogen appears low in this demo rule set; use the lab/KVK recommendation before purchasing.':'Avoid extra nitrogen without a crop-specific recommendation.');if(Number.isFinite(pp))notes.push(pp<10?'Phosphorus appears low in this demo rule set; verify with the lab before application.':'Avoid routine phosphorus loading without a recommendation.');if(Number.isFinite(kk))notes.push(kk<120?'Potassium appears low in this demo rule set; confirm crop and soil context before application.':'Maintain potassium only according to the crop-specific plan.');setPlan(notes.length?notes:['Enter lab values to generate a crop-specific action plan.'])};return <section className="container page"><div className="page-title"><div><span className="eyebrow">HARVEST + SOIL INTELLIGENCE</span><h1>Forecast the harvest before it happens.</h1><p>Variety, district timing, weather and eventually Sentinel-2 NDVI can drive pre-positioning and dynamic pricing. Soil reports should become actions, not another PDF in a drawer.</p></div></div><div className="metrics"><div className="metric"><CalendarDays/><b>{selected.harvest||'—'}</b><span>field harvest estimate</span></div><div className="metric"><Leaf/><b>{selected.variety||'Paddy'}</b><span>crop variety</span></div><div className="metric"><Truck/><b>{selected.block||'—'}</b><span>planning block</span></div><div className="metric"><ShieldCheck/><b>{weather?.daily?.precipitation_probability_max?.[0] ?? '—'}%</b><span>rain chance today</span></div></div><div className="split"><div className="panel"><div className="panel-title"><h3>Harvest forecast inputs</h3><span className="pill">Explainable</span></div><div className="detail-grid"><Stat label="Variety" value={selected.variety||'Not set'}/><Stat label="Expected harvest" value={selected.harvest||'Not set'}/><Stat label="Weather" value={weather?'Live advisory':'Unavailable'}/><Stat label="Satellite maturity" value="Sentinel-2 connector required"/></div><div className="note"><Satellite size={17}/><div><b>Production rule</b><span>Use Sentinel-2 NDVI as a maturity signal and explain the forecast; do not present a satellite estimate as a cadastral or agronomic fact without calibration.</span></div></div><button className="secondary" onClick={()=>onNotify('Harvest forecast job is ready for Sentinel-2/Bhuvan integration')}>Prepare forecast job</button></div><div className="panel green"><div className="panel-title"><h3>Soil report → action plan</h3><span className="pill">KVK / lab values</span></div><div className="form-grid"><label>pH<input type="number" step="0.1" value={pH} onChange={e=>setPH(e.target.value)} placeholder="7.2"/></label><label>N mg/kg<input type="number" value={n} onChange={e=>setN(e.target.value)} placeholder="280"/></label><label>P mg/kg<input type="number" value={p} onChange={e=>setP(e.target.value)} placeholder="12"/></label><label>K mg/kg<input type="number" value={k} onChange={e=>setK(e.target.value)} placeholder="120"/></label></div><button className="secondary" onClick={makePlan}>Generate action plan</button>{plan&&<div className="answer"><ClipboardCheck size={17}/><div>{plan.map((x,i)=><p key={i}>{x}</p>)}</div></div>}<small className="source-note">This is an interface-layer demo. Do not buy/apply inputs from these rules; use an accredited soil lab/KVK recommendation for field decisions.</small></div></div></section>}

function Auth({onClose,onNotify}){const[phone,setPhone]=useState('');const[otp,setOtp]=useState('');const[sent,setSent]=useState(false);const[consent,setConsent]=useState(false);const[busy,setBusy]=useState(false);const send=async()=>{if(!supabase)return onNotify('Connect the dedicated NIRDHOOM Supabase project to enable phone OTP');if(!/^\+91\d{10}$/.test(phone))return onNotify('Use an Indian number in +91XXXXXXXXXX format');if(!consent)return onNotify('Consent is required before creating the farmer account');setBusy(true);const{error}=await supabase.auth.signInWithOtp({phone,options:{channel:'sms'}});setBusy(false);if(error)onNotify(error.message);else setSent(true)};const verify=async()=>{if(!supabase||!consent)return;setBusy(true);const{data,error}=await supabase.auth.verifyOtp({phone,token:otp,type:'sms'});if(error){setBusy(false);return onNotify(error.message)}if(data.session?.user){await supabase.from('profiles').upsert({id:data.session.user.id,phone,consent_status:'GRANTED'},{onConflict:'id'});await supabase.from('consents').upsert({profile_id:data.session.user.id,consent_type:'farmer_network',version:'2026-09-27',accepted_at:new Date().toISOString(),source:'web_phone_otp',revoked_at:null},{onConflict:'profile_id,consent_type,version'});onNotify('Phone verified and farmer consent recorded');onClose()}setBusy(false)};return <div className="overlay"><div className="modal auth"><div className="modal-head"><div><span className="eyebrow">FARMER ACCOUNT</span><h2>{sent?'Enter OTP':'Phone-first onboarding'}</h2></div><button onClick={onClose}><X/></button></div><p className="modal-copy">NIRDHOOM uses passwordless phone OTP. Consent is stored separately so land, crop and operational data can be governed without storing raw Aadhaar.</p><label>Mobile number<input inputMode="tel" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+919876543210" disabled={sent}/></label>{sent&&<label>6-digit OTP<input inputMode="numeric" maxLength="6" value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,''))} placeholder="123456"/></label>}<label className="consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>I consent to NIRDHOOM using my submitted farmer, field and operational data for clearance, evidence, payment and residue matching as described in the production privacy policy.</span></label>{!sent?<button className="primary wide" disabled={busy||!consent} onClick={send}>{busy?'Sending…':'Send OTP'} <ArrowRight size={17}/></button>:<button className="primary wide" disabled={busy||otp.length!==6} onClick={verify}>{busy?'Verifying…':'Verify OTP'} <CheckCircle2 size={17}/></button>}</div></div>}

function Sathi({onClose,field,session,onNotify,language}){const[q,setQ]=useState('');const[answer,setAnswer]=useState('');const[asking,setAsking]=useState(false);const sendWhatsApp=async()=>{if(!session?.user?.phone)return onNotify('Verify your phone account first');try{const r=await fetch('/api/notify/whatsapp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({to:session.user.phone,text:answer})});if(!r.ok)throw new Error();onNotify('WhatsApp message sent')}catch{onNotify('WhatsApp is not configured yet')}};const ask=async()=>{if(!q.trim())return;setAsking(true);try{const r=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json',...(session?.access_token?{Authorization:`Bearer ${session.access_token}`}:{})},body:JSON.stringify({question:q,field,context:{booking_status:field.status,booking_id:field.bookingId||null,payment_status:field.paymentStatus||null,language:language}})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Assistant unavailable');setAnswer(data.answer)}catch{const l=q.toLowerCase();let a=`For ${field.village||'your field'}, this record shows ${field.acres} acres of ${field.variety||field.crop}. `;if(l.includes('book')||l.includes('clear'))a+=`The current status is ${pretty(field.status).toLowerCase()}. Open Book Clearance to request a slot.`;else if(l.includes('money')||l.includes('pay'))a+=`The displayed amount is ${field.payout?money(field.payout):'not set'}; final settlement must come from the payment ledger.`;else if(l.includes('machine')||l.includes('baler'))a+=`The current record shows ${field.machine||'no machine assigned'}. Live ETA requires dispatch/GPS data.`;else a+='I can help with booking, field status, machine assignment, verification, weather and residue pathways.';setAnswer(a)}finally{setAsking(false)}};return <div className="overlay"><div className="modal sathi"><div className="modal-head"><div><span className="eyebrow">NIRDHOOM SATHI</span><h2>Field assistant</h2></div><button onClick={onClose}><X/></button></div><div className="sathi-context"><MapPin size={16}/><b>{field.village}</b><span>{field.acres} acres · {field.variety}</span></div><div className="voice-note"><Mic size={17}/><span>Punjabi/WhatsApp voice is the next channel; answers are grounded in the selected field record.</span></div><div className="quick"><button onClick={()=>setQ('When should I clear my field?')}>When should I clear?</button><button onClick={()=>setQ('Where is my machine?')}>Where is my machine?</button><button onClick={()=>setQ('How will I get paid?')}>How do I get paid?</button></div><div className="ask"><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder="Ask about your field…"/><button className="primary" disabled={asking||!q.trim()} onClick={ask}>{asking?'Thinking…':'Ask'}</button></div>{answer&&<div className="answer"><MessageCircle size={17}/><div>{answer}<button className="secondary" onClick={sendWhatsApp}>Send to WhatsApp</button></div></div>}</div></div>}

function Network({onClose,onNavigate}){const items=[['Farmer','fields, booking, tracking','fields'],['Operator','jobs, GPS, proof','operator'],['Dispatch','VRP routes, exceptions','dispatch'],['Verification','FIRMS + evidence audit','verify'],['Marketplace','lots, buyers, contracts','market'],['Harvest intelligence','forecast + weather','intelligence'],['Carbon','evidence + registry layer','carbon']];return <div className="overlay"><div className="modal network"><div className="modal-head"><div><span className="eyebrow">NETWORK MODE</span><h2>Operational surfaces</h2></div><button onClick={onClose}><X/></button></div><p className="modal-copy">Farmer mode stays the default. Network roles share the data model but use separate permissions and workflows.</p><div className="network-list">{items.map(([a,b,target],i)=><button key={a} onClick={()=>{onClose();onNavigate(target)}}><span>{i+1}</span><div><b>{a}</b><small>{b}</small></div><ChevronRight size={17}/></button>)}</div></div></div>}
function NotificationDock({notifications,onRead}){return <div className="notification-dock"><div className="dock-head"><b>Updates</b><span>{notifications.filter(n=>!n.read_at).length} unread</span></div>{notifications.map(n=><button className={n.read_at?'notice read':'notice'} key={n.id} onClick={()=>onRead(n.id)}><div><b>{n.title}</b><span>{n.body}</span></div><Check size={15}/></button>)}</div>}
function Payments({selected,booking,notice,session}){const[ledger,setLedger]=useState(null);const[loading,setLoading]=useState(false);const load=async()=>{if(!supabase||!session?.user||!booking?.dbId)return;const{data}=await supabase.from('payments').select('*').eq('booking_id',booking.dbId).maybeSingle();setLedger(data||null)};useEffect(()=>{load();if(!booking?.dbId)return;const id=setInterval(load,10000);return()=>clearInterval(id)},[booking?.dbId,session?.user?.id]);const amount=ledger?.amount||booking?.total||selected.payout||0;const state=ledger?.status||notice?.status||'PENDING';const requestPayout=async()=>{setLoading(true);try{const r=await fetch('/api/payments/initiate',{method:'POST',headers:{'Content-Type':'application/json',...(session?.access_token?{Authorization:`Bearer ${session.access_token}`}:{})},body:JSON.stringify({booking_id:booking?.dbId,amount})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Payout initiation unavailable');await load();}catch(e){setLedger(x=>x);alert(e.message)}finally{setLoading(false)}};return <section className="container page narrow"><div className="page-title"><div><span className="eyebrow">PAYMENTS</span><h1>Per-acre payout trail</h1><p>Only provider webhooks can move a payout to a terminal state. The browser never marks money as paid.</p></div></div><div className="payment-card panel"><div className="payment-top"><div><span className="eyebrow">CURRENT FIELD</span><h2>{selected.village||selected.khasra}</h2><span>{selected.acres} acres · {selected.variety}</span></div><div className={'payment-status '+state.toLowerCase()}><CircleDollarSign size={18}/>{state}</div></div><div className="payment-amount">{money(amount)}<small>{ledger?'authoritative ledger':'quote / demo amount'}</small></div><div className="payment-steps">{[['BOOKING','Request recorded'],['CLEARANCE','Field cleared'],['VERIFICATION','Evidence reviewed'],['PAYMENT','Provider settles']].map((x,i)=>{const active=(state==='PAID')||(state==='PROCESSING'&&i===3)||(state==='PENDING'&&i===0);return <div key={i} className={active?'active':''}><span>{i+1}</span><b>{x[0]}</b><small>{x[1]}</small></div>})}</div><div className="note"><ShieldCheck size={17}/><div><b>{ledger?.provider_reference?'Provider event recorded':'No provider settlement yet'}</b><span>{ledger?.provider_reference?`Reference ${ledger.provider_reference} · ${ledger.settled_at||ledger.webhook_received_at||'webhook received'}`:'Connect RazorpayX/Cashfree and configure the signed webhook before enabling real payouts.'}</span></div></div>{booking?.dbId&&state==='PENDING'&&<button className="secondary wide" disabled={loading} onClick={requestPayout}>{loading?'Starting…':'Initialize provider payout'}</button>}</div><div className="panel"><span className="eyebrow">PAYOUT CONTRACT</span><div className="detail-grid"><Stat label="Provider" value={ledger?.provider||'Not connected'}/><Stat label="Reference" value={ledger?.provider_reference||'Pending webhook'}/><Stat label="Currency" value="INR"/><Stat label="Idempotency" value={ledger?.idempotency_key||'Server generated'}/></div></div></section>}


if (import.meta.env.PROD && 'serviceWorker' in navigator) window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));
createRoot(document.getElementById('root')).render(<App/>);
